type ProductCategory = "Bakery" | "Floral";
type ProductUnit = "each" | "dozen" | "bunch" | "box";
type StockReason = "Received" | "Sold" | "Spoiled" | "Adjustment";

interface Product {
  id: ProductId;
  name: string;
  category: ProductCategory;
  unitPrice: number;
  unit: ProductUnit;
  stockOnHand: number;
  reorderLevel: number;
