interface StoreState {
  products: Product[];
  orders: Order[];
  movements: StockMovement[];
  customers: { id: string; status: string; updatedAt: string }[];
  reports: { id: string; status: string; updatedAt: string }[];
  sellers: { id: string; status: string; updatedAt: string }[];
  managers: { id: string; status: string; updatedAt: string }[];
