function findProductById(productId: ProductId): ProductLookupOutcome {
  if (typeof productId !== "string" || productId.length === 0) {
    return { found: false, error: "Malformed product id" };
  }
  for (const product of store.products) {
    if (product.id === productId) {
      return { found: true, value: product };
