    if (order.id === orderId) {
      return { found: true, value: order };
    }
  }
  return { found: false, error: "Order not found: " + orderId };
}

function replaceProduct(updated: Product): void {
  for (let i = 0; i < store.products.length; i += 1) {
    if (store.products[i].id === updated.id) {
      store.products[i] = updated;
      return;
    }
  }
