/**
 * Report whether a transition between two order statuses is legal.
 * Legal: Draft to Confirmed, Confirmed to Ready, Ready to Fulfilled,
 * Draft to Cancelled, Confirmed to Cancelled. Everything else, including
 * any transition out of Fulfilled or Cancelled, is refused.
 *
 * @param from - the current order status
 * @param to - the attempted target status
 * @returns true when the transition is permitted, false otherwise
 */
function canTransition(from: OrderStatus, to: OrderStatus): boolean { // req-6
  if (from === "Draft" && to === "Confirmed") {
    return true;
  }
  if (from === "Confirmed" && to === "Ready") {
    return true;
  }
  if (from === "Ready" && to === "Fulfilled") {
    return true;
  }
  if (from === "Draft" && to === "Cancelled") {
    return true;
  }
  if (from === "Confirmed" && to === "Cancelled") {
    return true;
  }
  return false;
}

/**
 * Confirm a Draft order: validate that every line's product is active and has
 * enough stock, then atomically decrement each product's stored count and
 * append one Sold movement per line. On any shortfall no stock or movement is
 * written and the order keeps its status. Confirming a non-Draft order is
 * refused. Stored counts are re-derived from the movement log so the value
 * written is authoritative.
 *
 * @param orderId - the id of the order to confirm
 * @returns the outcome carrying the confirmed order, per-line shortfalls,
 *          appended movements and any error message
 */
async function confirmOrder(orderId: OrderId): Promise<ConfirmOrderResult> { // req-4
  const lookup = findOrderById(orderId);
  if (!lookup.found) {
    return { ok: false, order: emptyOrder(orderId), shortfalls: [], movements: [], error: lookup.error };
  }
  const order: Order = lookup.value;
  if (!canTransition(order.status, "Confirmed")) {
    return {
      ok: false,
      order: order,
      shortfalls: [],
      movements: [],
      error: "Illegal transition from " + order.status + " to Confirmed",
    };
  }
  if (order.lines.length === 0) {
    return { ok: false, order: order, shortfalls: [], movements: [], error: "Cannot confirm an order with no lines" };
  }
  const shortfalls: LineShortfall[] = [];
  const resolved: { product: Product; line: OrderLine }[] = [];
  for (const line of order.lines) {
    const productLookup = findProductById(line.productId);
    if (!productLookup.found) {
      shortfalls.push({ productId: line.productId, shortfall: line.quantity });
      continue;
    }
    if (!productLookup.value.active) {
      shortfalls.push({ productId: line.productId, shortfall: line.quantity });
      continue;
    }
    const difference = line.quantity - productLookup.value.stockOnHand;
    if (difference > 0) {
      shortfalls.push({ productId: line.productId, shortfall: difference });
      continue;
    }
    resolved.push({ product: productLookup.value, line: line });
  }
  if (shortfalls.length > 0) {
    return { ok: false, order: order, shortfalls: shortfalls, movements: [], error: "Insufficient stock" };
  }
  const movements: StockMovement[] = [];
  for (const entry of resolved) {
    const currentCount = reconstructCountFor(entry.product.id);
    const resultingCount = currentCount - entry.line.quantity;
    if (resultingCount < 0) {
      return { ok: false, order: order, shortfalls: [{ productId: entry.product.id, shortfall: -resultingCount }], movements: [], error: "Insufficient stock" };
    }
    const updated: Product = { ...entry.product, stockOnHand: resultingCount };
    replaceProduct(updated);
    const movement: StockMovement = {
      id: nextId("mov"),
      productId: entry.product.id,
      delta: -entry.line.quantity,
      reason: "Sold",
      timestamp: clock(),
      resultingCount: resultingCount,
    };
    store.movements.push(movement);
    movements.push(movement);
  }
  const confirmed: Order = { ...order, status: "Confirmed" };
  replaceOrder(confirmed);
  return { ok: true, order: confirmed, shortfalls: [], movements: movements, error: "" };
