/**
 * Cancel a Draft or Confirmed order: restore stock for every line and append a
 * restoration movement for each, then set the status to Cancelled. Cancelling
 * a Ready, Fulfilled or Cancelled order is refused and restores no stock.
 *
 * @param orderId - the id of the order to cancel
 * @returns the cancelled order
 */
async function cancelOrder(orderId: OrderId): Promise<Order> { // req-5
  const lookup = findOrderById(orderId);
  if (!lookup.found) {
    return emptyOrder(orderId);
  }
  const order: Order = lookup.value;
  if (!canTransition(order.status, "Cancelled")) {
    return order;
  }
  for (const line of order.lines) {
    const productLookup = findProductById(line.productId);
    if (!productLookup.found) {
      continue;
    }
    const currentCount = reconstructCountFor(line.productId);
    const resultingCount = currentCount + line.quantity;
    const updated: Product = { ...productLookup.value, stockOnHand: resultingCount };
    replaceProduct(updated);
    store.movements.push({
      id: nextId("mov"),
      productId: line.productId,
      delta: line.quantity,
      reason: "Adjustment",
      timestamp: clock(),
      resultingCount: resultingCount,
    });
  }
  const cancelled: Order = { ...order, status: "Cancelled" };
  replaceOrder(cancelled);
  return cancelled;
}

/**
 * Receive stock for a product: increment the stored count and append a
 * Received movement. A non-positive quantity is refused with no write.
 *
 * @param productId - the id of the product receiving stock
 * @param quantity - the positive number of units received
 * @returns the appended stock movement
 */
async function receiveStock(productId: ProductId, quantity: number): Promise<StockMovement> { // req-7
  const lookup = findProductById(productId);
  if (!lookup.found) {
    return { id: "", productId: productId, delta: 0, reason: "Received", timestamp: clock(), resultingCount: 0 };
  }
  if (!Number.isInteger(quantity) || quantity <= 0) {
    return { id: "", productId: productId, delta: 0, reason: "Received", timestamp: clock(), resultingCount: lookup.value.stockOnHand };
  }
  const currentCount = reconstructCountFor(productId);
  const resultingCount = currentCount + quantity;
  const updated: Product = { ...lookup.value, stockOnHand: resultingCount };
  replaceProduct(updated);
  const movement: StockMovement = {
    id: nextId("mov"),
    productId: productId,
    delta: quantity,
    reason: "Received",
    timestamp: clock(),
    resultingCount: resultingCount,
  };
  store.movements.push(movement);
  return movement;
}

/**
 * Perform a manual stock adjustment with a signed delta and a required reason.
 * A zero delta is recorded as a no-op movement so the reconstruction check
 * still agrees. An empty or whitespace-only reason is rejected and a delta
 * that would take the count below zero is refused, both without any write.
 *
 * @param productId - the id of the product to adjust
 * @param delta - the signed integer change to apply
 * @param reason - a non-empty justification for the adjustment
 * @returns the appended Adjustment movement
 */
async function adjustStock(productId: ProductId, delta: number, reason: string): Promise<StockMovement> { // req-7
  const lookup = findProductById(productId);
  if (!lookup.found) {
    return { id: "", productId: productId, delta: 0, reason: "Adjustment", timestamp: clock(), resultingCount: 0 };
  }
  const currentCount = reconstructCountFor(productId);
  if (typeof reason !== "string" || reason.trim().length === 0) {
    return { id: "", productId: productId, delta: 0, reason: "Adjustment", timestamp: clock(), resultingCount: currentCount };
  }
  if (!Number.isInteger(delta)) {
    return { id: "", productId: productId, delta: 0, reason: "Adjustment", timestamp: clock(), resultingCount: currentCount };
  }
  const resultingCount = currentCount + delta;
  if (resultingCount < 0) {
    return { id: "", productId: productId, delta: 0, reason: "Adjustment", timestamp: clock(), resultingCount: currentCount };
  }
  const updated: Product = { ...lookup.value, stockOnHand: resultingCount };
  replaceProduct(updated);
  const movement: StockMovement = {
    id: nextId("mov"),
    productId: productId,
    delta: delta,
    reason: "Adjustment",
    timestamp: clock(),
    resultingCount: resultingCount,
  };
  store.movements.push(movement);
  return movement;
}

/**
 * Replay a product's movement log and compare the reconstructed running sum
 * against the stored stock count, reporting whether they agree. The stored
 * count is never trusted on its own.
 *
 * @param productId - the id of the product to check
 * @returns the stored count, the reconstructed count and the agreement flag
 */
async function reconstructStockCount(productId: ProductId): Promise<StockReconstructionResult> { // req-8
  const lookup = findProductById(productId);
  const storedCount = lookup.found ? lookup.value.stockOnHand : 0;
  const reconstructedCount = reconstructCountFor(productId);
