    productId: productId,
    storedCount: storedCount,
    reconstructedCount: reconstructedCount,
    agrees: storedCount === reconstructedCount,
  };
}

/**
 * List products whose stock on hand is at or below their reorder level, sorted
 * by how far below the reorder level they are (descending), each with a
 * suggested reorder quantity that restores the reorder level and a small buffer.
 *
 * @returns the low-stock dashboard items
 */
async function listLowStock(): Promise<LowStockItem[]> { // req-9
  const items: LowStockItem[] = [];
  for (const product of store.products) {
    if (!product.active) {
      continue;
    }
    if (product.stockOnHand <= product.reorderLevel) {
      const distanceBelow = product.reorderLevel - product.stockOnHand;
      items.push({
        product: product,
        stockOnHand: product.stockOnHand,
        reorderLevel: product.reorderLevel,
        distanceBelow: distanceBelow,
        suggestedReorderQuantity: distanceBelow > 0 ? distanceBelow : 1,
      });
    }
  }
  items.sort((a: LowStockItem, b: LowStockItem): number => b.distanceBelow - a.distanceBelow);
  return items;
}

function reconstructCountFor(productId: ProductId): number {
  let count = 0;
  for (const movement of store.movements) {
    if (movement.productId === productId) {
      count += movement.delta;
    }
  }
  return count;
}

